param([Parameter(Mandatory=$true)][ValidateSet('2024','2025')][string]$RevitVersion,[string]$Configuration='Release')
$ErrorActionPreference='Stop';& "$PSScriptRoot\build.ps1" -RevitVersion $RevitVersion -Configuration $Configuration
$framework=if($RevitVersion-eq'2025'){'net8.0-windows'}else{'net48'};$source="$PSScriptRoot\src\SAUDICO.Federate.Revit$RevitVersion\bin\$Configuration\$framework";$root="$env:APPDATA\Autodesk\Revit\Addins\$RevitVersion";$target="$root\SAUDICO.Federate";New-Item -ItemType Directory -Force $target|Out-Null;Copy-Item "$source\*" $target -Recurse -Force;Copy-Item "$PSScriptRoot\src\SAUDICO.Federate.Revit$RevitVersion\SAUDICO.Federate.Revit$RevitVersion.addin" $root -Force;Write-Host "Installed SAUDICO Federate for Revit $RevitVersion" -ForegroundColor Green
